        if (d.image) meta.image = d.image;
        if (d.imageSize) meta.imageSize = d.imageSize;
        if (d.imageTitle) meta.imageTitle = d.imageTitle;
        if (d.customLeft != null) meta.customLeft = d.customLeft;
